import{z as o,x as B,o as r,c,q as i,j as s,D as e,d as t,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"交叉货币互换定价","description":"","frontmatter":{"title":"交叉货币互换定价","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/xccy-swap-pricing.md","filePath":"quant/xccy-swap-pricing.md","lastUpdated":1791413859000}'),p={name:"quant/xccy-swap-pricing.md"};function d(F,a,u,D,h,m){const n=B("Mermaid");return r(),c("div",null,[a[2]||(a[2]=i('<h1 id="交叉货币互换定价" tabindex="-1">交叉货币互换定价 <a class="header-anchor" href="#交叉货币互换定价" aria-label="Permalink to &quot;交叉货币互换定价&quot;">​</a></h1><div class="epigraph"><p>交叉货币基差把「用外国曲线贴现外国腿」这条教科书等式打破；本金交换与基差报价是同一件事的两面。</p><footer>—— 多曲线与 xccy 基差见 Fujii, Shimada and Takahashi 以及市场上 USD/JPY、EUR/USD 基差报价惯例</footer></div><p><a href="/quant/fx-barrier-touch">上一课</a>还在 FX 期权路径。交叉货币互换（xccy swap）的缺口是<strong>线性产品里的基差</strong>：交换本金、交换浮息，报价却是一腿上的基差利差，而不是 GK 的 \\(\\sigma\\)。主干 <a href="/quant/xccy-basis">交叉货币基差</a> 已写经济含义。本课写定价引擎如何把基差曲线与两条单货币曲线、FX 远期一起用，接到后课商品之前把 FX 线性产品收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书：把外币腿用外币 OIS 贴现，本币腿用本币 OIS，用 FX 远期把未来现金流换成同一货币，价值应为零。危机后同一信用等级的美元与欧元折现仍差一截，市场用 USD/EUR 基差互换把差报价出来。问题是引擎：三条曲线（USD 贴现、EUR 贴现、EUR 预测或反过来）加 FX 远期，必须联合校准到存款、单货币互换、FX swap 与 xccy 基差，否则期权里用的 \\(F\\) 与互换里用的 \\(F\\) 不一致。<span class="marginnote">交叉货币互换可以理解成「两笔不同币种的贷款互相持有」：期初你把美元本金换给我、我把欧元本金换给你，期间各付各的浮动利息，期末按约定汇率换回本金。它同时是一笔 FX 交易和一笔利率交易，所以定价要两条曲线加一条汇率远期一起上。</span></p><p>本金交换在期初与期末。基差主要补偿的是「借一种货币、贷另一种」的资金差，不是预期即期的方向。把 xccy 当 FX 方向性产品，会与 Delta 对冲的远期簿重复计算。</p>',6)),(r(),s(A,null,{default:e(()=>[l(n,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E6%9C%9F%E5%88%9D%EF%BC%9A%E6%8C%89%E5%8D%B3%E6%9C%9F%E4%BA%A4%E6%8D%A2%E6%9C%AC%E9%87%91%20%E4%BB%98%20USD%20%E6%94%B6%20EUR%22%5D%20--%3E%20TI%5B%22%E5%AD%98%E7%BB%AD%E6%9C%9F%EF%BC%9A%E6%AF%8F%E6%9C%9F%E4%BA%92%E4%BB%98%E6%B5%AE%E5%8A%A8%E5%88%A9%E6%81%AF%22%5D%0A%20%20TI%20--%3E%20B%5B%22%E5%9F%BA%E5%B7%AE%E5%88%A9%E5%B7%AE%E8%AE%B0%E5%9C%A8%E5%85%B6%E4%B8%AD%E4%B8%80%E6%9D%A1%E8%85%BF%E4%B8%8A%22%5D%0A%20%20TI%20--%3E%20TN%5B%22%E6%9C%9F%E6%9C%AB%EF%BC%9A%E6%8C%89%E6%9C%9F%E5%88%9D%E7%BA%A6%E5%AE%9A%E6%B1%87%E7%8E%87%E6%8D%A2%E5%9B%9E%E6%9C%AC%E9%87%91%22%5D%0A%20%20TN%20--%3E%20NP%5B%22%E5%87%80%E6%95%88%E6%9E%9C%EF%BC%9A%E8%B7%A8%E5%B8%81%E7%A7%8D%E8%9E%8D%E8%B5%84%20%E5%B7%B2%E9%94%81%E6%B1%87%E7%8E%87%20%E6%97%A0%E6%96%B9%E5%90%91%20FX%20%E6%95%9E%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p><span class="marginnote">常见误区：把基差利差当成 FX 观点。基差补偿的是「借一种币、贷另一种币」的资产负债表成本，与即期涨跌的方向无关；把 xccy 当方向性外汇产品，会与远期簿的 Delta 重复计算风险，对冲账本凭空多出一截。</span></p><h3 id="多曲线是约束-不是装饰" tabindex="-1">多曲线是约束，不是装饰 <a class="header-anchor" href="#多曲线是约束-不是装饰" aria-label="Permalink to &quot;多曲线是约束，不是装饰&quot;">​</a></h3><p><a href="/quant/multi-curve-ois">OIS 多曲线</a> 在单货币里已经把预测与贴现分开。xccy 再把贴现拆成按货币、按抵押货币。CSA 若以 USD 现金为抵押，欧元腿的贴现也不再是欧元 OIS。定价必须以净额集的抵押货币为准，这与 <a href="/quant/xva-bridge">XVA 桥</a> 同一逻辑。</p><p><span class="marginnote">基差可为负（日元长期如此）。模型允许负基差，并不等于允许负的单货币利率——后课移位是另一件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准顺序：先各货币 OIS 与 IBOR/RFR 预测，再 FX swap 短端，再 xccy 基差长端，检查再定价误差。估值：投影每条腿的浮息，用对应贴现曲线贴现，期初期末本金用 FX 与贴现换成报告货币。对冲：各货币 DV01 + FX Delta + 基差桶。不要用单一「外汇 Rho」代替基差桶。</p><p>MTM 与 reset：部分 xccy 有定期本金重设，降低 CVA 暴露，改变基差敏感度。条款要当状态机，不能当普通固定-浮动。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无基差时，FX 远期与利率平价一致，互换公平价差为零。有基差时，市场在说：用欧元抵押的欧元现金与用美元抵押的美元现金，不能通过 FX 无摩擦转换。定价核把这句写成贴现曲线的差。期权的 quanto 调整用的相关，与这条资金基差不是同一个 \\(\\rho\\)；不要把 xccy 基差当股权-FX 相关的代理。<span class="marginnote">直觉类比：基差像两国之间过桥的通行费。教科书假设桥免费（利率平价成立），市场发现过桥要占用桥的承重额度（银行的资产负债表与监管额度），于是开始收费。桥越挤（美元短缺）、养护成本越高（监管加码），通行费就越贵。</span></p>',9)),(r(),s(A,null,{default:e(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OIS%5B%22%E5%90%84%E8%B4%A7%E5%B8%81%20OIS%20%E4%B8%8E%E9%A2%84%E6%B5%8B%22%5D%20--%3E%20Joint%5B%22%E8%81%94%E5%90%88%E6%A0%A1%E5%87%86%22%5D%0A%20%20FXsw%5B%22FX%20swap%22%5D%20--%3E%20Joint%0A%20%20Basis%5B%22xccy%20%E5%9F%BA%E5%B7%AE%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20Joint%0A%20%20Joint%20--%3E%20PV%5B%22%E5%8F%8C%E8%85%BF%E5%8A%A0%E6%9C%AC%E9%87%91%E4%BA%A4%E6%8D%A2%E7%9A%84%20PV%22%5D%0A%20%20PV%20--%3E%20Hdg%5B%22DV01%20%E5%8A%A0%20FX%20Delta%20%E5%8A%A0%E5%9F%BA%E5%B7%AE%E6%A1%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[t("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"LIBOR 停用后的 RFR xccy、历史基差与新惯例不可混。流动性差的货币对只有短端 FX swap，长端基差外推是模型风险。XVA：xccy 暴露对 FX 高度敏感，CVA 与 IM 必须用同一 FX 动态。",-1)),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[t("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"xccy 定价是多曲线加 FX 远期加基差曲线的联合校准，不是 GK 的附属品。"),E("li",null,"本金交换与抵押货币决定贴现；对冲要单独的基差桶。"),E("li",null,"基差是资金与抵押，不是方向性 FX 观点。"),E("li",null,"出处：Fujii, Shimada and Takahashi 关于多货币曲线的工作；市场基差报价惯例。")],-1))])}const f=o(p,[["render",d]]);export{C as __pageData,f as default};
